Output6[Expected Approach] Hash Map and Prefix Sum Technique - O(n) Time and O(n) SpaceThe idea is to convert the problem into finding the longest subarray with zero sum. Replace every 0 with -1 so that a subarray with equal number of 0s and 1s results in a cumulative sum of 0.Traverse the array while maintaining a prefix sum. If the prefix sum becomes 0, the subarray from index 0 to the current index has equal 0s and 1s.  If a prefix sum repeats, the subarray between the previous index and the current index also has a zero sum.A hash map is used to store the first occurrence of each prefix sum, allowing us to compute and update the maximum subarray length efficiently.
            C++

    #include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

int maxLen(vector<int> &arr) {
    unordered_map<int, int> mp;

    int preSum = 0; 
    int res = 0; 

    // Traverse through the given array
    for (int i = 0; i < arr.size(); i++) {

        // Add current element to sum
      	// if current element is zero, add -1
        preSum += (arr[i] == 0) ? -1 : 1;

        // To handle sum = 0 at last index
        if (preSum == 0) 
            res = i + 1;

        // If this sum is seen before, then update 
      	// result with maximum
        if (mp.find(preSum) != mp.end())
            res = max(res, i - mp[preSum]);

		// Else put this sum in hash table
        else 
            mp[preSum] = i;
    }

    return res;
}

int main() {
    vector<int> arr = {1, 0, 0, 1, 0, 1, 1};

    cout << maxLen(arr) << endl;
    return 0;
}


